	public void writeEntityToNBT(NBTTagCompound nbttagcompound) {
		super.writeEntityToNBT(nbttagcompound);
		nbttagcompound.setInteger("bloodLevel", getBloodConsumed());
		nbttagcompound.setInteger("fleeingTick", fleeingTick);
	}

